import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_24_hrl_overview.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_24_hierarchy_interface.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_24_option_lifecycle.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_24_option_composition.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_24_driving_hrl_boundary.png",f=JSON.parse('{"title":"一个目标太大怎么办？分层强化学习与 Options 框架","description":"很多任务不是“动作难”，而是任务层次太长。自动驾驶先决定跟车、变道还是通过路口，再决定期望速度和轨迹，最后才输出转角与加速度。若所有决策都由同一个策略在每个控制周期直接完成，信用分配、探索和长时域规划会同时变难。Hierarchical Reinforcement Learning（分层强化学习，H","frontmatter":{"title":"一个目标太大怎么办？分层强化学习与 Options 框架","description":"很多任务不是“动作难”，而是任务层次太长。自动驾驶先决定跟车、变道还是通过路口，再决定期望速度和轨迹，最后才输出转角与加速度。若所有决策都由同一个策略在每个控制周期直接完成，信用分配、探索和长时域规划会同时变难。Hierarchical Reinforcement Learning（分层强化学习，H","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":8,"source":"2026-08-13/rl_series_24_hierarchical_options.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_24_hrl_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-24-hierarchical-options"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一个目标太大怎么办？分层强化学习与 Options 框架"}],["meta",{"property":"og:description","content":"很多任务不是“动作难”，而是任务层次太长。自动驾驶先决定跟车、变道还是通过路口，再决定期望速度和轨迹，最后才输出转角与加速度。若所有决策都由同一个策略在每个控制周期直接完成，信用分配、探索和长时域规划会同时变难。Hierarchical Reinforcement Learning（分层强化学习，H"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-24-hierarchical-options"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_24_hrl_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"一个目标太大怎么办？分层强化学习与 Options 框架"}],["meta",{"name":"twitter:description","content":"很多任务不是“动作难”，而是任务层次太长。自动驾驶先决定跟车、变道还是通过路口，再决定期望速度和轨迹，最后才输出转角与加速度。若所有决策都由同一个策略在每个控制周期直接完成，信用分配、探索和长时域规划会同时变难。Hierarchical Reinforcement Learning（分层强化学习，H"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_24_hrl_overview.png"}]],"prev":{"text":"失败也能变经验：目标条件强化学习与 HER 讲透了","link":"/rl/rl-series-23-her-goal-conditioned-rl"},"next":{"text":"不知道奖励怎么写？先用行为克隆学会专家怎么做","link":"/rl/rl-series-25-behavior-cloning"}},"headers":[],"relativePath":"rl/rl-series-24-hierarchical-options.md","filePath":"rl/rl-series-24-hierarchical-options.md","lastUpdated":null}'),c={name:"rl/rl-series-24-hierarchical-options.md"};function p(d,a,_,u,b,m){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="一个目标太大怎么办-分层强化学习与-options-框架" tabindex="-1">一个目标太大怎么办？分层强化学习与 Options 框架 <a class="header-anchor" href="#一个目标太大怎么办-分层强化学习与-options-框架" aria-label="Permalink to &quot;一个目标太大怎么办？分层强化学习与 Options 框架&quot;">​</a></h1><p>很多任务不是“动作难”，而是任务层次太长。自动驾驶先决定跟车、变道还是通过路口，再决定期望速度和轨迹，最后才输出转角与加速度。若所有决策都由同一个策略在每个控制周期直接完成，信用分配、探索和长时域规划会同时变难。Hierarchical Reinforcement Learning（分层强化学习，HRL）把任务拆成多个时间尺度，让高层选择子目标或技能，低层负责执行。</p><p>Options Framework（选项框架）把一个可持续多步执行的技能形式化为三部分：Initiation Set（启动集合）、Policy（内部策略）和 Termination Condition（终止条件）。它把原子动作提升为时间抽象动作，使智能体可以在“选择技能”和“执行技能”之间切换。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-分层解决时间尺度问题" tabindex="-1">1.1 分层解决时间尺度问题 <a class="header-anchor" href="#_1-1-分层解决时间尺度问题" aria-label="Permalink to &quot;1.1 分层解决时间尺度问题&quot;">​</a></h3><p>高层低频决定做什么，低层高频决定怎么做。层次不是简单多几个网络，而是明确决策频率、目标接口和责任边界。</p><h3 id="_1-2-option-是可调用的技能单元" tabindex="-1">1.2 Option 是可调用的技能单元 <a class="header-anchor" href="#_1-2-option-是可调用的技能单元" aria-label="Permalink to &quot;1.2 Option 是可调用的技能单元&quot;">​</a></h3><p>启动集合决定何时可用，内部策略决定动作，终止条件决定何时交还控制权。</p><h3 id="_1-3-子目标必须可达且可评价" tabindex="-1">1.3 子目标必须可达且可评价 <a class="header-anchor" href="#_1-3-子目标必须可达且可评价" aria-label="Permalink to &quot;1.3 子目标必须可达且可评价&quot;">​</a></h3><p>高层提出低层做不到的目标会产生无意义惩罚；低层完成目标但高层评价不清晰，也无法学会选择技能。</p><h3 id="_1-4-分层不自动带来安全和泛化" tabindex="-1">1.4 分层不自动带来安全和泛化 <a class="header-anchor" href="#_1-4-分层不自动带来安全和泛化" aria-label="Permalink to &quot;1.4 分层不自动带来安全和泛化&quot;">​</a></h3><p>层次可能提高样本效率，也可能引入高层—低层错配、技能边界错误和分布外组合问题。每层都需要独立验证。</p><p><img src="'+o+'" alt="高层任务选择、低层技能执行与环境反馈"></p><h2 id="二、为什么平坦策略难以处理长任务" tabindex="-1">二、为什么平坦策略难以处理长任务 <a class="header-anchor" href="#二、为什么平坦策略难以处理长任务" aria-label="Permalink to &quot;二、为什么平坦策略难以处理长任务&quot;">​</a></h2><h3 id="_2-1-每步动作都承载长期责任" tabindex="-1">2.1 每步动作都承载长期责任 <a class="header-anchor" href="#_2-1-每步动作都承载长期责任" aria-label="Permalink to &quot;2.1 每步动作都承载长期责任&quot;">​</a></h3><p>终点奖励要回溯数百个控制步，策略很难知道哪个动作促成了成功。</p><h3 id="_2-2-探索组合数快速增长" tabindex="-1">2.2 探索组合数快速增长 <a class="header-anchor" href="#_2-2-探索组合数快速增长" aria-label="Permalink to &quot;2.2 探索组合数快速增长&quot;">​</a></h3><p>不同动作序列、目标顺序和时间长度组合在一起，随机策略几乎不会碰到完整成功方案。</p><h3 id="_2-3-技能复用被隐藏" tabindex="-1">2.3 技能复用被隐藏 <a class="header-anchor" href="#_2-3-技能复用被隐藏" aria-label="Permalink to &quot;2.3 技能复用被隐藏&quot;">​</a></h3><p>“保持车道”“跟车”“变道”在多个路线中反复出现。平坦策略可能重复学习，而不会显式复用技能。</p><h3 id="_2-4-低层控制频率压过高层决策" tabindex="-1">2.4 低层控制频率压过高层决策 <a class="header-anchor" href="#_2-4-低层控制频率压过高层决策" aria-label="Permalink to &quot;2.4 低层控制频率压过高层决策&quot;">​</a></h3><p>如果每个控制周期都重新决定任务意图，高层目标容易抖动，低层也没有时间完成当前技能。</p><h2 id="三、分层策略的接口怎样定义" tabindex="-1">三、分层策略的接口怎样定义 <a class="header-anchor" href="#三、分层策略的接口怎样定义" aria-label="Permalink to &quot;三、分层策略的接口怎样定义&quot;">​</a></h2><h3 id="_3-1-高层策略输出子目标或技能" tabindex="-1">3.1 高层策略输出子目标或技能 <a class="header-anchor" href="#_3-1-高层策略输出子目标或技能" aria-label="Permalink to &quot;3.1 高层策略输出子目标或技能&quot;">​</a></h3><p>高层可输出离散技能 ID、连续目标状态、期望速度或局部路径。输出必须是低层能解释的接口。</p><h3 id="_3-2-低层策略接收状态与高层指令" tabindex="-1">3.2 低层策略接收状态与高层指令 <a class="header-anchor" href="#_3-2-低层策略接收状态与高层指令" aria-label="Permalink to &quot;3.2 低层策略接收状态与高层指令&quot;">​</a></h3><p>低层策略表示为 (\\pi_l(a|s,z))，其中 (z) 是子目标或技能条件。</p><h3 id="_3-3-终止信号控制时间抽象" tabindex="-1">3.3 终止信号控制时间抽象 <a class="header-anchor" href="#_3-3-终止信号控制时间抽象" aria-label="Permalink to &quot;3.3 终止信号控制时间抽象&quot;">​</a></h3><p>低层可以在达到目标、超时、危险或不可达时终止。终止条件不应只由网络分数决定，还要包含硬约束。</p><h3 id="_3-4-高层奖励应反映子任务进展" tabindex="-1">3.4 高层奖励应反映子任务进展 <a class="header-anchor" href="#_3-4-高层奖励应反映子任务进展" aria-label="Permalink to &quot;3.4 高层奖励应反映子任务进展&quot;">​</a></h3><p>高层不必直接使用每个控制步的原始奖励，可以使用技能完成、时间成本、风险和最终任务结果构造半马尔可夫回报。</p><p><img src="'+n+'" alt="分层强化学习的状态、子目标和终止接口"></p><h2 id="四、options-框架的三部分" tabindex="-1">四、Options 框架的三部分 <a class="header-anchor" href="#四、options-框架的三部分" aria-label="Permalink to &quot;四、Options 框架的三部分&quot;">​</a></h2><h3 id="_4-1-启动集合决定技能可用范围" tabindex="-1">4.1 启动集合决定技能可用范围 <a class="header-anchor" href="#_4-1-启动集合决定技能可用范围" aria-label="Permalink to &quot;4.1 启动集合决定技能可用范围&quot;">​</a></h3><p>Option (o) 只有在状态属于 (I_o) 时才能被高层选择。例如变道技能需要存在可行目标车道。</p><h3 id="_4-2-内部策略决定技能动作" tabindex="-1">4.2 内部策略决定技能动作 <a class="header-anchor" href="#_4-2-内部策略决定技能动作" aria-label="Permalink to &quot;4.2 内部策略决定技能动作&quot;">​</a></h3><p>(\\pi_o(a|s)) 在技能持续期间输出原子动作，也可以接收目标参数。</p><h3 id="_4-3-终止函数决定技能何时结束" tabindex="-1">4.3 终止函数决定技能何时结束 <a class="header-anchor" href="#_4-3-终止函数决定技能何时结束" aria-label="Permalink to &quot;4.3 终止函数决定技能何时结束&quot;">​</a></h3><p>(\\beta_o(s)) 表示在状态 (s) 终止技能的概率或规则。终止太早会让技能碎片化，太晚会阻塞高层改策略。</p><h3 id="_4-4-option-形成半马尔可夫决策过程" tabindex="-1">4.4 Option 形成半马尔可夫决策过程 <a class="header-anchor" href="#_4-4-option-形成半马尔可夫决策过程" aria-label="Permalink to &quot;4.4 Option 形成半马尔可夫决策过程&quot;">​</a></h3><p>一个 option 可能持续多个时间步，下一次高层决策的时间不固定。因此高层目标需要使用持续时长折扣，而不是盲目套一步 Bellman 公式。</p><p><img src="'+h+'" alt="Option 的启动、内部执行、终止与高层重选生命周期"></p><h2 id="五、子目标怎样被学习和复用" tabindex="-1">五、子目标怎样被学习和复用 <a class="header-anchor" href="#五、子目标怎样被学习和复用" aria-label="Permalink to &quot;五、子目标怎样被学习和复用&quot;">​</a></h2><h3 id="_5-1-手工技能适合建立第一版基线" tabindex="-1">5.1 手工技能适合建立第一版基线 <a class="header-anchor" href="#_5-1-手工技能适合建立第一版基线" aria-label="Permalink to &quot;5.1 手工技能适合建立第一版基线&quot;">​</a></h3><p>经典控制器、规则或规划器可以提供跟车、避障和停车技能，先验证高层组合逻辑再学习低层。</p><h3 id="_5-2-目标条件低层适合连续技能" tabindex="-1">5.2 目标条件低层适合连续技能 <a class="header-anchor" href="#_5-2-目标条件低层适合连续技能" aria-label="Permalink to &quot;5.2 目标条件低层适合连续技能&quot;">​</a></h3><p>低层学习从任意状态到目标状态的控制，HER 可以增加失败轨迹利用率。</p><h3 id="_5-3-高层可以学习技能选择" tabindex="-1">5.3 高层可以学习技能选择 <a class="header-anchor" href="#_5-3-高层可以学习技能选择" aria-label="Permalink to &quot;5.3 高层可以学习技能选择&quot;">​</a></h3><p>高层根据状态、任务目标和历史选择 option。其评价必须同时考虑成功、时间、风险和技能切换成本。</p><h3 id="_5-4-技能库需要覆盖和独立测试" tabindex="-1">5.4 技能库需要覆盖和独立测试 <a class="header-anchor" href="#_5-4-技能库需要覆盖和独立测试" aria-label="Permalink to &quot;5.4 技能库需要覆盖和独立测试&quot;">​</a></h3><p>技能复用要求不同场景中具有稳定语义。只在训练路线有效的技能不能直接当通用模块。</p><p><img src="'+l+'" alt="技能库、选项选择与组合泛化"></p><h2 id="六、分层训练的几种方式" tabindex="-1">六、分层训练的几种方式 <a class="header-anchor" href="#六、分层训练的几种方式" aria-label="Permalink to &quot;六、分层训练的几种方式&quot;">​</a></h2><h3 id="_6-1-先固定低层再训练高层" tabindex="-1">6.1 先固定低层再训练高层 <a class="header-anchor" href="#_6-1-先固定低层再训练高层" aria-label="Permalink to &quot;6.1 先固定低层再训练高层&quot;">​</a></h3><p>低层技能先达到可接受成功率，高层只学习调用顺序。优点是接口清楚，缺点是低层错误会限制高层上限。</p><h3 id="_6-2-联合训练高层与低层" tabindex="-1">6.2 联合训练高层与低层 <a class="header-anchor" href="#_6-2-联合训练高层与低层" aria-label="Permalink to &quot;6.2 联合训练高层与低层&quot;">​</a></h3><p>两层同时更新，适应性更强，但高层目标变化会让低层数据分布非平稳，训练诊断更复杂。</p><h3 id="_6-3-用示范初始化技能" tabindex="-1">6.3 用示范初始化技能 <a class="header-anchor" href="#_6-3-用示范初始化技能" aria-label="Permalink to &quot;6.3 用示范初始化技能&quot;">​</a></h3><p>专家轨迹可切分为技能片段，再用模仿学习初始化低层。切分边界和专家意图不明确时，技能语义会不稳定。</p><h3 id="_6-4-用内在奖励鼓励技能进展" tabindex="-1">6.4 用内在奖励鼓励技能进展 <a class="header-anchor" href="#_6-4-用内在奖励鼓励技能进展" aria-label="Permalink to &quot;6.4 用内在奖励鼓励技能进展&quot;">​</a></h3><p>低层可使用目标距离或内在进展奖励，高层仍需用真实任务指标检查是否出现局部投机。</p><h2 id="七、自动驾驶中分层的边界" tabindex="-1">七、自动驾驶中分层的边界 <a class="header-anchor" href="#七、自动驾驶中分层的边界" aria-label="Permalink to &quot;七、自动驾驶中分层的边界&quot;">​</a></h2><h3 id="_7-1-高层不是安全监督器" tabindex="-1">7.1 高层不是安全监督器 <a class="header-anchor" href="#_7-1-高层不是安全监督器" aria-label="Permalink to &quot;7.1 高层不是安全监督器&quot;">​</a></h3><p>高层选择“变道”不代表变道一定安全。可行性检查、预测碰撞和控制屏障应位于独立安全层。</p><h3 id="_7-2-低层技能不能覆盖高层盲区" tabindex="-1">7.2 低层技能不能覆盖高层盲区 <a class="header-anchor" href="#_7-2-低层技能不能覆盖高层盲区" aria-label="Permalink to &quot;7.2 低层技能不能覆盖高层盲区&quot;">​</a></h3><p>技能库没有“施工区绕行”时，高层不能靠重复调用普通跟车技能解决新场景。</p><h3 id="_7-3-技能切换必须有滞回和最小持续时间" tabindex="-1">7.3 技能切换必须有滞回和最小持续时间 <a class="header-anchor" href="#_7-3-技能切换必须有滞回和最小持续时间" aria-label="Permalink to &quot;7.3 技能切换必须有滞回和最小持续时间&quot;">​</a></h3><p>在多个技能价值接近时，高层可能频繁切换。滞回、冷却时间和切换代价可以降低抖动。</p><p><img src="'+s+'" alt="自动驾驶分层决策与独立安全层"></p><h2 id="八、一个最小实验怎样设计" tabindex="-1">八、一个最小实验怎样设计 <a class="header-anchor" href="#八、一个最小实验怎样设计" aria-label="Permalink to &quot;八、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_8-1-选取有明显子任务的二维导航" tabindex="-1">8.1 选取有明显子任务的二维导航 <a class="header-anchor" href="#_8-1-选取有明显子任务的二维导航" aria-label="Permalink to &quot;8.1 选取有明显子任务的二维导航&quot;">​</a></h3><p>把到达多个房间、绕障碍和返回基地作为高层目标，把移动动作作为低层控制。</p><h3 id="_8-2-比较平坦策略与分层策略" tabindex="-1">8.2 比较平坦策略与分层策略 <a class="header-anchor" href="#_8-2-比较平坦策略与分层策略" aria-label="Permalink to &quot;8.2 比较平坦策略与分层策略&quot;">​</a></h3><p>统一总环境步和网络参数，比较成功率、样本效率、技能复用和目标切换次数。</p><h3 id="_8-3-固定与学习低层分别测试" tabindex="-1">8.3 固定与学习低层分别测试 <a class="header-anchor" href="#_8-3-固定与学习低层分别测试" aria-label="Permalink to &quot;8.3 固定与学习低层分别测试&quot;">​</a></h3><p>先使用规划器低层，再替换成目标条件策略，判断收益来自层次本身还是低层能力。</p><h3 id="_8-4-做技能缺失和扰动测试" tabindex="-1">8.4 做技能缺失和扰动测试 <a class="header-anchor" href="#_8-4-做技能缺失和扰动测试" aria-label="Permalink to &quot;8.4 做技能缺失和扰动测试&quot;">​</a></h3><p>移除关键技能、改变目标顺序和加入动力学扰动，观察高层是否能识别不可达而不是盲目调用。</p><h2 id="九、最常见的实现错误" tabindex="-1">九、最常见的实现错误 <a class="header-anchor" href="#九、最常见的实现错误" aria-label="Permalink to &quot;九、最常见的实现错误&quot;">​</a></h2><h3 id="_9-1-高层与低层目标使用不同状态定义" tabindex="-1">9.1 高层与低层目标使用不同状态定义 <a class="header-anchor" href="#_9-1-高层与低层目标使用不同状态定义" aria-label="Permalink to &quot;9.1 高层与低层目标使用不同状态定义&quot;">​</a></h3><p>高层认为到达了目标，低层的坐标或姿态判定却不满足，训练会出现虚假成功。</p><h3 id="_9-2-终止条件只依赖奖励" tabindex="-1">9.2 终止条件只依赖奖励 <a class="header-anchor" href="#_9-2-终止条件只依赖奖励" aria-label="Permalink to &quot;9.2 终止条件只依赖奖励&quot;">​</a></h3><p>危险、超时和不可达状态必须能强制终止 option，不能等待奖励自然出现。</p><h3 id="_9-3-把-option-当作固定动作宏" tabindex="-1">9.3 把 option 当作固定动作宏 <a class="header-anchor" href="#_9-3-把-option-当作固定动作宏" aria-label="Permalink to &quot;9.3 把 option 当作固定动作宏&quot;">​</a></h3><p>Option 内部策略可以依赖状态并提前终止，不是预先录制的一段固定动作序列。</p><h3 id="_9-4-只报告最终回报" tabindex="-1">9.4 只报告最终回报 <a class="header-anchor" href="#_9-4-只报告最终回报" aria-label="Permalink to &quot;9.4 只报告最终回报&quot;">​</a></h3><p>还应报告技能成功率、持续时长、切换频率、不可达目标比例和安全介入率。</p><h2 id="十、学到什么程度才算掌握" tabindex="-1">十、学到什么程度才算掌握 <a class="header-anchor" href="#十、学到什么程度才算掌握" aria-label="Permalink to &quot;十、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_10-1-能画出两层策略数据流" tabindex="-1">10.1 能画出两层策略数据流 <a class="header-anchor" href="#_10-1-能画出两层策略数据流" aria-label="Permalink to &quot;10.1 能画出两层策略数据流&quot;">​</a></h3><p>你应能标出高层输出、低层输入、option 持续时间、终止信号和安全层位置。</p><h3 id="_10-2-能解释半马尔可夫回报" tabindex="-1">10.2 能解释半马尔可夫回报 <a class="header-anchor" href="#_10-2-能解释半马尔可夫回报" aria-label="Permalink to &quot;10.2 能解释半马尔可夫回报&quot;">​</a></h3><p>你应能说明 option 持续多步后，高层折扣和奖励累计为什么不同于一步动作。</p><h3 id="_10-3-能设计技能复用实验" tabindex="-1">10.3 能设计技能复用实验 <a class="header-anchor" href="#_10-3-能设计技能复用实验" aria-label="Permalink to &quot;10.3 能设计技能复用实验&quot;">​</a></h3><p>你应能在新目标、新顺序和新动力学下检查技能是否真的可组合。</p><h3 id="_10-4-能进入模仿学习" tabindex="-1">10.4 能进入模仿学习 <a class="header-anchor" href="#_10-4-能进入模仿学习" aria-label="Permalink to &quot;10.4 能进入模仿学习&quot;">​</a></h3><p>下一篇将从“专家怎么做”出发，解释行为克隆如何把示范转为策略。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="http://www.cs.ualberta.ca/~sutton/papers/SPS-aij.pdf" target="_blank" rel="noreferrer">Sutton、Precup 与 Singh《Between MDPs and Semi-MDPs: A Framework for Temporal Abstraction in Reinforcement Learning》</a></p><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter10/chapter10.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十章分层强化学习部分</a></p><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter11/chapter11.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十一章模仿学习导航</a></p>',100)])])}const k=e(c,[["render",p]]);export{f as __pageData,k as default};
